  1→//! Configuration file discovery and loading.
  2→//!
  3→//! This module handles finding and loading configuration files from
  4→//! various locations in the correct priority order.
  5→
  6→use crate::config::extends::ExtendsResolver;
  7→use crate::config::merger::merge_configs;
  8→use crate::config::schema::BivvyConfig;
  9→use crate::error::{BivvyError, Result};
 10→use std::fs;
 11→use std::path::{Path, PathBuf};
 12→
 13→/// Paths to configuration files in priority order (later overrides earlier).
 14→///
 15→/// Merge order:
 16→/// 1. Remote base configs (from `extends:`)
 17→/// 2. User global config (`~/.bivvy/config.yml`)
 18→/// 3. Project config (`.bivvy/config.yml`)
 19→/// 4. Local overrides (`.bivvy/config.local.yml`)
 20→#[derive(Debug, Clone)]
 21→pub struct ConfigPaths {
 22→    /// Remote base config (if extends: is used)
 23→    pub extends: Vec<PathBuf>,
 24→
 25→    /// User's global config: ~/.bivvy/config.yml
 26→    pub user_global: Option<PathBuf>,
 27→
 28→    /// Project config: .bivvy/config.yml
 29→    pub project: Option<PathBuf>,
 30→
 31→    /// Local overrides: .bivvy/config.local.yml
 32→    pub project_local: Option<PathBuf>,
 33→}
 34→
 35→impl ConfigPaths {
 36→    /// Discover config files for the given project root.
 37→    pub fn discover(project_root: &Path) -> Self {
 38→        Self {
 39→            extends: Vec::new(), // Populated later after parsing project config
 40→            user_global: Self::find_user_global(),
 41→            project: Self::find_project_config(project_root),
 42→            project_local: Self::find_project_local(project_root),
 43→        }
 44→    }
 45→
 46→    /// Find user's global config at ~/.bivvy/config.yml
 47→    fn find_user_global() -> Option<PathBuf> {
 48→        let path = dirs::home_dir()?.join(".bivvy").join("config.yml");
 49→        if path.exists() {
 50→            Some(path)
 51→        } else {
 52→            None
 53→        }
 54→    }
 55→
 56→    /// Find project config at .bivvy/config.yml
 57→    fn find_project_config(project_root: &Path) -> Option<PathBuf> {
 58→        let path = project_root.join(".bivvy").join("config.yml");
 59→        if path.exists() {
 60→            Some(path)
 61→        } else {
 62→            None
 63→        }
 64→    }
 65→
 66→    /// Find local overrides at .bivvy/config.local.yml
 67→    fn find_project_local(project_root: &Path) -> Option<PathBuf> {
 68→        let path = project_root.join(".bivvy").join("config.local.yml");
 69→        if path.exists() {
 70→            Some(path)
 71→        } else {
 72→            None
 73→        }
 74→    }
 75→
 76→    /// Returns all existing config paths in merge order.
 77→    pub fn all_existing(&self) -> Vec<&PathBuf> {
 78→        let mut paths = Vec::new();
 79→
 80→        for p in &self.extends {
 81→            paths.push(p);
 82→        }
 83→
 84→        if let Some(p) = &self.user_global {
 85→            paths.push(p);
 86→        }
 87→
 88→        if let Some(p) = &self.project {
 89→            paths.push(p);
 90→        }
 91→
 92→        if let Some(p) = &self.project_local {
 93→            paths.push(p);
 94→        }
 95→
 96→        paths
 97→    }
 98→
 99→    /// Check if any project config exists.
100→    pub fn has_project_config(&self) -> bool {
101→        self.project.is_some()
102→    }
103→}
104→
105→/// Find the project root by walking up from current directory.
106→///
107→/// Looks for:
108→/// 1. `.bivvy` directory (primary indicator)
109→/// 2. `.git` directory (fallback)
110→///
111→/// # Returns
112→///
113→/// The path to the project root, or None if not found.
114→pub fn find_project_root(start: &Path) -> Option<PathBuf> {
115→    let mut current = start.to_path_buf();
116→
117→    loop {
118→        // Check for .bivvy directory
119→        if current.join(".bivvy").is_dir() {
120→            return Some(current);
121→        }
122→
123→        // Check for .git directory (fallback)
124→        if current.join(".git").exists() {
125→            return Some(current);
126→        }
127→
128→        // Move up one directory
129→        if !current.pop() {
130→            return None;
131→        }
132→    }
133→}
134→
135→/// Load a single config file and parse it into BivvyConfig.
136→///
137→/// # Errors
138→///
139→/// Returns `ConfigNotFound` if the file doesn't exist.
140→/// Returns `ConfigParseError` if the YAML is invalid.
141→pub fn load_config_file(path: &Path) -> Result<BivvyConfig> {
142→    let content = fs::read_to_string(path).map_err(|e| {
143→        if e.kind() == std::io::ErrorKind::NotFound {
144→            BivvyError::ConfigNotFound {
145→                path: path.to_path_buf(),
146→            }
147→        } else {
148→            BivvyError::Io(e)
149→        }
150→    })?;

  1→//! Project index management.
  2→//!
  3→//! This module provides the [`ProjectIndex`] for tracking all known
  4→//! projects that Bivvy has been used with.
  5→
  6→use chrono::{DateTime, Utc};
  7→use serde::{Deserialize, Serialize};
  8→use std::collections::HashMap;
  9→use std::fs;
 10→use std::path::PathBuf;
 11→
 12→use super::ProjectId;
 13→
 14→/// Index of all known projects.
 15→#[derive(Debug, Clone, Default, Serialize, Deserialize)]
 16→pub struct ProjectIndex {
 17→    pub projects: HashMap<String, ProjectEntry>,
 18→}
 19→
 20→/// Entry for a project in the index.
 21→#[derive(Debug, Clone, Serialize, Deserialize)]
 22→pub struct ProjectEntry {
 23→    pub path: String,
 24→    pub git_remote: Option<String>,
 25→    pub name: String,
 26→    pub last_accessed: DateTime<Utc>,
 27→}
 28→
 29→impl ProjectIndex {
 30→    /// Get the index file path.
 31→    pub fn file_path() -> PathBuf {
 32→        dirs::home_dir()
 33→            .unwrap_or_else(|| PathBuf::from("~"))
 34→            .join(".bivvy")
 35→            .join("projects")
 36→            .join("index.yml")
 37→    }
 38→
 39→    /// Load the project index.
 40→    pub fn load() -> crate::error::Result<Self> {
 41→        let path = Self::file_path();
 42→
 43→        if !path.exists() {
 44→            return Ok(Self::default());
 45→        }
 46→
 47→        let content = fs::read_to_string(&path)?;
 48→        let index: Self = serde_yaml::from_str(&content).map_err(|e| {
 49→            crate::error::BivvyError::ConfigParseError {
 50→                path,
 51→                message: e.to_string(),
 52→            }
 53→        })?;
 54→
 55→        Ok(index)
 56→    }
 57→
 58→    /// Save the project index using atomic write.
 59→    ///
 60→    /// Uses the write-to-temp-then-rename pattern to prevent corruption.
 61→    pub fn save(&self) -> crate::error::Result<()> {
 62→        let path = Self::file_path();
 63→
 64→        if let Some(parent) = path.parent() {
 65→            fs::create_dir_all(parent)?;
 66→        }
 67→
 68→        let content = serde_yaml::to_string(self).map_err(|e| {
 69→            crate::error::BivvyError::ConfigValidationError {
 70→                message: format!("Failed to serialize index: {}", e),
 71→            }
 72→        })?;
 73→
 74→        // Atomic write: write to temp file, then rename
 75→        let temp_path = path.with_extension("yml.tmp");
 76→        fs::write(&temp_path, &content)?;
 77→        fs::rename(&temp_path, &path)?;
 78→
 79→        Ok(())
 80→    }
 81→
 82→    /// Update or add a project to the index.
 83→    pub fn update(&mut self, project_id: &ProjectId) {
 84→        let entry = ProjectEntry {
 85→            path: project_id.path().to_string_lossy().to_string(),
 86→            git_remote: project_id.git_remote().map(String::from),
 87→            name: project_id.name().to_string(),
 88→            last_accessed: Utc::now(),
 89→        };
 90→        self.projects.insert(project_id.hash().to_string(), entry);
 91→    }
 92→
 93→    /// Remove projects that no longer exist on disk.
 94→    pub fn prune(&mut self) -> Vec<String> {
 95→        let mut removed = Vec::new();
 96→
 97→        self.projects.retain(|hash, entry| {
 98→            let exists = std::path::Path::new(&entry.path).exists();
 99→            if !exists {
100→                removed.push(hash.clone());
101→            }
102→            exists
103→        });
104→
105→        removed
106→    }
107→
108→    /// List all projects.
109→    pub fn list(&self) -> impl Iterator<Item = (&str, &ProjectEntry)> {
110→        self.projects.iter().map(|(k, v)| (k.as_str(), v))
111→    }
112→
113→    /// Get a project by hash.
114→    pub fn get(&self, hash: &str) -> Option<&ProjectEntry> {
115→        self.projects.get(hash)
116→    }
117→
118→    /// Number of tracked projects.
119→    pub fn len(&self) -> usize {
120→        self.projects.len()
121→    }
122→
123→    /// Check if index is empty.
124→    pub fn is_empty(&self) -> bool {
125→        self.projects.is_empty()
126→    }
127→}
