                status: StepStatus::Success,
                last_run: Some(Utc::now()),
                duration_ms: Some(1000),
                watches_hash: None,
            },
        );

        state.save(&project).unwrap();

        let loaded = StateStore::load(&project).unwrap();
        assert!(loaded.get_step("test_step").is_some());
        assert_eq!(
