    #[test]
    fn user_global_config_uses_platform_config_dir() {
        // If a user global config path is returned, it should use the
        // platform config directory, not ~/.bivvy
        let temp = TempDir::new().unwrap();
        let paths = ConfigPaths::discover(temp.path());
        // user_global may be None if no config exists, but the method
        // that builds the path should not use .bivvy
        // We test the path construction by checking the private method
        // indirectly: if config_dir/bivvy/config.yml exists, it would be found
        if let Some(config_dir) = crate::paths::config_dir() {
